import { Box, Chip, IconButton, styled } from "@mui/material";
import Typography from "@mui/material/Typography";
import CustomDataGrid from "src/@core/components/data-grid";
import RemoveRedEyeIcon from "@mui/icons-material/RemoveRedEye";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import { useEffect, useState } from "react";
function TableContactUs({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  toggleView,
  status,
}) {
  const statusColors = {
    inactive: "#3A3541AD",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  const [activeData, setActiveData] = useState([]);
  const [inActiveData, setInActiveData] = useState([]);
  useEffect(() => {
    const activeRows = rows.filter((row) => row.status === "active");
    setActiveData(activeRows);
    const inActiveRows = rows.filter((row) => row.status === "inactive");
    setInActiveData(inActiveRows);
  }, [rows]);
  const displayedRows =
    status === "active"
      ? activeData
      : status === "inactive"
      ? inActiveData
      : rows;

  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={displayedRows}
      columns={[
        {
          field: "title",
          minWidth: 200,
          flex: 1,
          sortable: false,
          headerName: "Title",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.title}>
              {row.title}
            </Typography>
          ),
        },
        {
          field: "email",
          minWidth: 250,
          flex: 1,
          sortable: false,
          headerName: "Email",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.email}>
              {row.email}
            </Typography>
          ),
        },
        {
          field: "time",
          minWidth: 200,
          flex: 1,
          sortable: false,
          headerName: "Time",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.time}>
              {row.time}
            </Typography>
          ),
        },
        {
          field: "status",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Status",
          renderCell: ({ row }) => <CustomChip label={row.status} />,
        },
        {
          field: "Actions",
          flex: 0,
          minWidth: 170,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleEdit(e, "edit", row)}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => toggleDelete(e, row)}
              >
                <DeleteIcon />
              </IconButton>
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleView(e, row)}
              >
                <RemoveRedEyeIcon />
              </IconButton>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
}

export default TableContactUs;
