import { useEffect, useState, useRef } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import TableContactUs from "src/views/tables/TableContactUs";
import DialogContact from "src/views/dialog/DialogContact";
import DialogViewContactInfo from "src/views/dialog/DialogViewContactInfo";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";

import { useCallback } from "react";

const ContactUsPage = () => {
  const searchTimeoutRef = useRef();

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("active");
  const [contactData, setContactData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [contactFormDialogOpen, setContactFormDialogOpen] = useState(false);
  const [contactViewFormDialogOpen, setContactViewFormDialogOpen] =
    useState(false);
  const [contactFormDialogMode, setContactFormDialogMode] = useState("add");
  const [contactToEdit, setContactToEdit] = useState(null);

  const toggleContactFormDialog = (e, mode = "add", contactToEdit = null) => {
    setContactFormDialogOpen((prev) => !prev);
    setContactToEdit(contactToEdit);
    setContactFormDialogMode(mode);
  };

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [contactDetailsToDelete, setContactDetailsToDelete] = useState(null);
  const [diableAddButton, setDiableAddButton] = useState(false);

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setContactDetailsToDelete(dataToDelete);
  };
  const toggleContactViewFormDialog = (e, contactToEdit = null) => {
    setContactViewFormDialogOpen((prev) => !prev);
    setContactToEdit(contactToEdit);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ContactUs.list, { params })
      .then((response) => {
        setContactData(response.data.data);
        setTotalCount(response.data.data.totalCount);
        const responseData = response.data.data;
        if (responseData.length === 3) {
          setDiableAddButton(true);
        } else {
          setDiableAddButton(false); // Enable the button if there is no data
        }
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  //SEARCH
  useEffect(() => {
    if (!search) {
      // If search input is empty, show all data
      setContactData(contactData);
    } else {
      // Filter the contactData based on the search value
      const filtered = contactData.filter(
        (item) =>
          item.title.toLowerCase().includes(search.toLowerCase()) || // Example field 'title'
          item.email.toLowerCase().includes(search.toLowerCase()) // Example field 'email'
      );
      setContactData(filtered); // Set the filtered data
    }
  }, [search, contactData]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.ContactUs.delete(contactDetailsToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, contactDetailsToDelete, pageSize, search]
  );
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Contact Us" />
            </Typography>
          }
          action={
            <Button
              disabled={diableAddButton}
              variant="contained"
              onClick={toggleContactFormDialog}
            >
              Add Contact Details
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "all" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"all"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box>
            <Box sx={{ p: 5 }}>
              <TableContactUs
                status={status}
                search={search}
                loading={loading}
                rows={contactData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleEdit={toggleContactFormDialog}
                toggleView={toggleContactViewFormDialog}
                toggleDelete={toggleConfirmationDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogContact
        mode={contactFormDialogMode}
        open={contactFormDialogOpen}
        toggle={toggleContactFormDialog}
        dataToEdit={contactToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Contact Us"
        subtitle="Are you sure you want to delete this Contact Details?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
      <DialogViewContactInfo
        open={contactViewFormDialogOpen}
        toggle={toggleContactViewFormDialog}
        dataToEdit={contactToEdit}
      />
    </>
  );
};

export default ContactUsPage;
